        <div v-if="appSettings.localHistoryEnabled" class="wizard-update"><p>数据更新程序：{{appSettings.localHistoryUpdaterPath||'尚未选择'}}</p><button :disabled="!!busy" @click="browseUpdater">选择 数据更新.exe</button><button :disabled="!!busy||!appSettings.stockDbStatus?.updaterAvailable||appSettings.stockDbStatus?.state==='running_external'" @click="updateHistory">更新历史数据</button></div>
        <details><summary>连接非默认地址的本地 stockdb</summary><label class="wizard-url">服务地址 <input v-model="historyUrl" type="url" placeholder="http://127.0.0.1:7899"><button :disabled="!!busy" @click="saveHistoryUrl">保存并测试</button></label></details>
